public void postLoad()
{
    next postLoad();
    if (this.PricingRuleHeader)
    {
        GUPPricingRule pricingRule = GUPPricingRule::find(this.PricingRuleHeader);
        if (pricingRule.PriceAttributeGroupName)
        {
            int num = 1;
            str baseFieldName = "Header";
            GUPPricingRuleCondition ruleCondition;
            GUPPricingAttributeLink attributeLink;
            while select ruleCondition 
            where ruleCondition.RuleId == this.PricingRuleHeader 
            join attributeLink 
            order by attributeLink.Priority asc
            where ruleCondition.ConditionAttribute == attributeLink.RecId
            {
                this.setFieldValue(baseFieldName + int2Str(num), ruleCondition.ConditionValue);
                num++;
            }
        }
    }

    if (this.PricingRuleLine)
    {
        GUPPricingRule pricingRule = GUPPricingRule::find(this.PricingRuleLine);
        if (pricingRule.PriceAttributeGroupName)
        {
            int num = 1;
            str baseFieldName = "Line";
            GUPPricingRuleCondition ruleCondition;
            GUPPricingAttributeLink attributeLink;
            while select ruleCondition
            where ruleCondition.RuleId == this.PricingRuleLine
            join attributeLink
            order by attributeLink.Priority asc
            where ruleCondition.ConditionAttribute == attributeLink.RecId
            {
                this.setFieldValue(baseFieldName + int2Str(num), ruleCondition.ConditionValue);
                num++;
            }
        }
    }
}

public boolean insertEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    boolean ret = true;
    if (_dataSourceCtx.name() == dataEntityDataSourceStr(SalesOpenSalesPriceJournalLineEntity, PriceDiscAdmTrans))
    {
        PriceDiscAdmTrans trans = _dataSourceCtx.getBuffer();
        trans.ItemCode = PriceDiscProductCodeType::Table;

        if (this.PriceComponentCombination)
        {
            GUPPriceComponentCodePriceAttributeGroupCombination combination = this.getPriceAttributeGroupCombination();
            trans.PriceComponentCombination = combination.RecId;

            // insert header pricing rule condition
            if (combination.HeaderPriceAttributeGroupName)
            {
                ttsbegin;
                GUPPricingRule rule = GUPPricingRule::newPricingRule(combination.HeaderPriceAttributeGroupName, GUPPricingRuleExclusionType::Customer);
                trans.PricingRuleHeader = rule.RecId;

                int num = 1;
                str baseFieldName = "Header";
                GUPPricingAttributeLink attributeLink;
                while select attributeLink
                    order by attributeLink.Priority asc
                    where attributeLink.PriceAttributeGroupName == combination.HeaderPriceAttributeGroupName
                {
                    this.createOrUpdatePricingRuleCondition(null, rule.RecId, attributeLink.RecId, this.getFieldValue(baseFieldName + int2Str(num)), baseFieldName + int2Str(num));
                    num ++;
                }
                ttscommit;
            }

            // insert line pricing rule condition
            if (combination.LinePriceAttributeGroupName)
            {
                ttsbegin;
                GUPPricingRule rule = GUPPricingRule::newPricingRule(combination.LinePriceAttributeGroupName, GUPPricingRuleExclusionType::Product);
                trans.PricingRuleLine = rule.RecId;

                int num = 1;
                str baseFieldName = "Line";
                GUPPricingAttributeLink attributeLink;
                while select attributeLink
                    order by attributeLink.Priority asc
                    where attributeLink.PriceAttributeGroupName == combination.LinePriceAttributeGroupName
                {
                    this.createOrUpdatePricingRuleCondition(null, rule.RecId, attributeLink.RecId, this.getFieldValue(baseFieldName + int2Str(num)), baseFieldName + int2Str(num));
                    num ++;
                }
                ttscommit;
            }
        }
    }
    ret = next insertEntityDataSource(_entityCtx, _dataSourceCtx);
    return ret;
}

public boolean updateEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    boolean ret = true;
    if (_dataSourceCtx.name() == dataEntityDataSourceStr(SalesOpenSalesPriceJournalLineEntity, PriceDiscAdmTrans))
    {
        PriceDiscAdmTrans trans = _dataSourceCtx.getBuffer();
        trans.ItemCode = PriceDiscProductCodeType::Table;

        if (this.PriceComponentCombination)
        {
            GUPPriceComponentCodePriceAttributeGroupCombination combination = this.getPriceAttributeGroupCombination();
            trans.PriceComponentCombination = combination.RecId;

            if (combination.HeaderPriceAttributeGroupName)
            {
                // insert/update header pricing rule condition
                ttsbegin;
                GUPPricingRule rule = GUPPricingRule::find(trans.PricingRuleHeader, true);
                if (rule.PriceAttributeGroupName != combination.HeaderPriceAttributeGroupName)
                {
                    rule.selectForUpdate(true);
                    rule.delete();
                    rule = null;
                }

                if (!rule)
                {
                    rule = GUPPricingRule::newPricingRule(combination.HeaderPriceAttributeGroupName, GUPPricingRuleExclusionType::Customer);
                    trans.PricingRuleHeader = rule.RecId;
                }
                int num = 1;
                str baseFieldName = "Header";
                GUPPricingAttributeLink attributeLink;
                while select attributeLink
                    order by attributeLink.Priority asc
                    where attributeLink.PriceAttributeGroupName == combination.HeaderPriceAttributeGroupName
                {
                    GUPPricingRuleCondition ruleCondition = GUPPricingRuleCondition::find(rule.RecId, attributeLink.RecId, true);
                    this.createOrUpdatePricingRuleCondition(ruleCondition, rule.RecId, attributeLink.RecId, this.getFieldValue(baseFieldName + int2Str(num)), baseFieldName + int2Str(num));
                    num ++;
                }
                ttscommit;
            }
            else
            {
                trans.PricingRuleHeader = 0;
            }

            if (combination.LinePriceAttributeGroupName)
            {
                // insert/update header pricing rule condition
                ttsbegin;
                GUPPricingRule rule = GUPPricingRule::find(trans.PricingRuleLine, true);
                if (rule.PriceAttributeGroupName != combination.LinePriceAttributeGroupName)
                {
                    rule.selectForUpdate(true);
                    rule.delete();
                    rule = null;
                }

                if (!rule)
                {
                    rule = GUPPricingRule::newPricingRule(combination.LinePriceAttributeGroupName, GUPPricingRuleExclusionType::Product);
                    trans.PricingRuleLine = rule.RecId;
                }
                int num = 1;
                str baseFieldName = "Line";
                GUPPricingAttributeLink attributeLink;
                while select attributeLink
                    order by attributeLink.Priority asc
                    where attributeLink.PriceAttributeGroupName == combination.LinePriceAttributeGroupName
                {
                    GUPPricingRuleCondition ruleCondition = GUPPricingRuleCondition::find(rule.RecId, attributeLink.RecId, true);
                    this.createOrUpdatePricingRuleCondition(ruleCondition, rule.RecId, attributeLink.RecId, this.getFieldValue(baseFieldName + int2Str(num)), baseFieldName + int2Str(num));
                    num ++;
                }
                ttscommit;
            }
            else
            {
                GUPPricingRule::find(trans.PricingRuleLine).delete();
                trans.PricingRuleLine = 0;
            }
        }
        else
        {
            trans.PricingRuleHeader = 0;
            trans.PricingRuleLine = 0;
        }
    }
    ret = next updateEntityDataSource(_entityCtx, _dataSourceCtx);
    return ret;
}

public void initializeEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    next initializeEntityDataSource(_entityCtx, _dataSourceCtx);
    if (_dataSourceCtx.name() ==  dataEntityDataSourceStr(SalesOpenSalesPriceJournalLineEntity, GUPPriceComponentCodePriceAttributeGroupCombination))
    {
        _dataSourceCtx.setDataSaved(true);
        _dataSourceCtx.setDatabaseOperation(DataEntityDatabaseOperation::Update);
    }
}
